#region

using Avalonia;
using Avalonia.Media;
using Avalonia.Styling;
using DemoViewer.NET.Services;
using DemoViewer.NET.TestSupport;
using DemoViewer.NET.Theming;
using TUnit.Core.Exceptions;

#endregion

namespace DemoViewer.NET.AppTests;

/// <summary>
///     samples/Themes/ holds each built-in theme written out as a complete user drop-in, id suffixed
///     <c>-json</c>. They are generated by <c>UiCapture export-themes</c>; these hold the files equal to that
///     export, and load them the way a user's file loads (the themes folder, then <see cref="ThemeRegistry.Reload" />)
///     to check every token resolves to the built-in's.
/// </summary>
[NotInParallel]
[Category("Integration")]
public class ThemeSampleFileTests
{
    private const string Suffix = "-json";

    private static string SamplesDir()
    {
        string? root = DemoTestHelper.FindRepoRoot();
        if (root is null)
        {
            throw new SkipTestException("repo root not found from the test bin");
        }

        return Path.Combine(root, "samples", "Themes");
    }

    // Copies the samples into a scratch config dir and runs the real drop-in scan over it.
    private static async Task WithSamplesLoaded(Action<ThemeRegistry> body)
    {
        string dir = Path.Combine(Path.GetTempPath(), "dv-theme-samples-" + Guid.NewGuid().ToString("N"));
        string themesDir = Path.Combine(dir, "themes");
        Directory.CreateDirectory(themesDir);
        foreach (string file in Directory.GetFiles(SamplesDir(), "*.json"))
        {
            File.Copy(file, Path.Combine(themesDir, Path.GetFileName(file)));
        }

        string? prior = Environment.GetEnvironmentVariable(AppPaths.ConfigDirEnvVar);
        Environment.SetEnvironmentVariable(AppPaths.ConfigDirEnvVar, dir);
        try
        {
            ThemeRegistry registry = new();
            registry.Reload();
            await HeadlessSession.RunOnUi(() =>
            {
                registry.Install(Application.Current!);
                try
                {
                    body(registry);
                }
                finally
                {
                    registry.Uninstall(Application.Current!);
                }

                return Task.CompletedTask;
            });
        }
        finally
        {
            Environment.SetEnvironmentVariable(AppPaths.ConfigDirEnvVar, prior);
            try
            {
                Directory.Delete(dir, true);
            }
            catch
            {
                /* best-effort */
            }
        }
    }

    [Test]
    public async Task EverySample_IsExactlyTheExportOfItsBuiltIn()
    {
        string[] files = [.. Directory.GetFiles(SamplesDir(), "*.json").Select(Path.GetFileName).Order()!];
        await Assert.That(files).IsEquivalentTo(BuiltInThemes.All.Select(ThemeExport.SampleFileName))
            .Because("one sample per built-in; run `UiCapture export-themes` to regenerate them");

        foreach (ThemePalette builtIn in BuiltInThemes.All)
        {
            string onDisk = (await File.ReadAllTextAsync(Path.Combine(SamplesDir(), ThemeExport.SampleFileName(builtIn))))
                .Replace("\r\n", "\n");
            await Assert.That(onDisk).IsEqualTo(ThemeExport.SampleFile(builtIn))
                .Because($"samples/Themes/{ThemeExport.SampleFileName(builtIn)} is stale; run `UiCapture export-themes`");
        }
    }

    [Test]
    public async Task EverySample_LoadsAsAUserTheme_WithNothingMissing()
    {
        Theme[] samples = [];
        IReadOnlyList<ThemeLoadProblem> problems = [];
        await WithSamplesLoaded(registry =>
        {
            samples = [.. registry.Themes.Where(t => t.Source == ThemeSource.User)];
            problems = registry.LoadProblems;
        });

        await Assert.That(problems).IsEmpty();
        await Assert.That(samples.Select(t => t.Id[..^Suffix.Length])).IsEquivalentTo(BuiltInThemes.All.Select(p => p.Id));
        foreach (Theme sample in samples)
        {
            await Assert.That(sample.MissingTokens).IsEmpty().Because(sample.Id);
            await Assert.That(sample.UnknownKeys).IsEmpty().Because(sample.Id);
        }
    }

    [Test]
    public async Task EachSample_ResolvesEveryToken_ExactlyAsItsBuiltIn()
    {
        List<string> diffs = [];
        await WithSamplesLoaded(registry =>
        {
            foreach (Theme sample in registry.Themes.Where(t => t.Source == ThemeSource.User))
            {
                ThemeVariant builtIn = registry.VariantFor(sample.Id[..^Suffix.Length]);
                ThemeVariant builtInBase = builtIn.InheritVariant ?? builtIn;
                if (!Equals(sample.Variant.InheritVariant, builtInBase))
                {
                    diffs.Add($"{sample.Id}: base {sample.Variant.InheritVariant}, built-in {builtInBase}");
                }

                foreach (string token in ThemeTokens.All)
                {
                    Application.Current!.TryGetResource(token, builtIn, out object? want);
                    Application.Current.TryGetResource(token, sample.Variant, out object? got);
                    if (!SameBrush(want, got))
                    {
                        diffs.Add($"{sample.Id} {token}: built-in {Describe(want)}, sample {Describe(got)}");
                    }
                }
            }
        });

        await Assert.That(diffs).IsEmpty().Because(string.Join("\n", diffs));
    }

    internal static bool SameBrush(object? a, object? b) => (a, b) switch
    {
        (ISolidColorBrush x, ISolidColorBrush y) => x.Color == y.Color,
        (ILinearGradientBrush x, ILinearGradientBrush y) => ThemeGradient.FromBrush(x).Equals(ThemeGradient.FromBrush(y)),
        _ => false
    };

    internal static string Describe(object? brush) => brush switch
    {
        ISolidColorBrush b => b.Color.ToString(),
        null => "(none)",
        _ => brush.GetType().Name
    };
}
